import{_ as a,o as s,c as t,ag as e}from"./chunks/framework.BwSLX4ak.js";const c=JSON.parse('{"title":"安装与部署","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/installation.md","filePath":"shitbot/installation.md"}'),l={name:"shitbot/installation.md"};function n(o,i,h,p,d,k){return s(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="安装与部署" tabindex="-1">安装与部署 <a class="header-anchor" href="#安装与部署" aria-label="Permalink to &quot;安装与部署&quot;">​</a></h1><h2 id="运行要求" tabindex="-1">运行要求 <a class="header-anchor" href="#运行要求" aria-label="Permalink to &quot;运行要求&quot;">​</a></h2><p>ShitBot 需要一个支持 OneBot v11 正向 WebSocket 的 QQ 机器人实现。插件会主动连接 OneBot，不接受反向 WebSocket 连接。</p><p>可以使用 <a href="https://github.com/LLOneBot/LuckyLilliaBot" target="_blank" rel="noreferrer">LuckyLilliaBot</a> 或其他兼容实现。安装前准备好：</p><ul><li>OneBot 正向 WebSocket 地址；</li><li>OneBot Access Token，如果 OneBot 已启用鉴权；</li><li>允许使用机器人的 QQ 群号；</li><li>与运行平台匹配的 ShitBot JAR。</li></ul><h2 id="选择平台-jar" tabindex="-1">选择平台 JAR <a class="header-anchor" href="#选择平台-jar" aria-label="Permalink to &quot;选择平台 JAR&quot;">​</a></h2><p>从 <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载：</p><table tabindex="0"><thead><tr><th>平台</th><th>JAR</th><th>插件运行时 Java</th></tr></thead><tbody><tr><td>Spigot、Paper、Folia、CatServer 等 Bukkit 服务端</td><td><code>ShitBotSpigot-*.jar</code></td><td>Java 8+</td></tr><tr><td>BungeeCord</td><td><code>ShitBotBungee-*.jar</code></td><td>Java 8+</td></tr><tr><td>Velocity</td><td><code>ShitBotVelocity-*.jar</code></td><td>Java 21+</td></tr><tr><td>Nukkit-MOT</td><td><code>ShitBotNukkit-*.jar</code></td><td>Java 17+</td></tr></tbody></table><p>这里列的是 ShitBot JAR 的最低字节码要求。服务端核心自身可能要求更高版本的 Java，应同时满足核心要求。某个 Release 没有对应平台 JAR 时，表示该版本没有发布该平台构建，不能改用其他平台 JAR。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><ol><li>停止服务器或代理。</li><li>将对应平台 JAR 放入该实例的 <code>plugins/</code> 目录。</li><li>启动实例，等待 ShitBot 生成插件数据目录。</li><li>停止实例。</li><li>打开生成的 <code>config.yml</code>、<code>commands.yml</code>、<code>lang/</code> 语言文件和 <code>templates/default.yml</code> 图片模板。</li><li>按下文完成最小配置后重新启动。</li></ol><p>不要修改 JAR 内部的默认配置。后续版本增加配置项时，应先备份当前配置，再对照新版本生成的配置补充内容。</p><h2 id="onebot-最小配置" tabindex="-1">OneBot 最小配置 <a class="header-anchor" href="#onebot-最小配置" aria-label="Permalink to &quot;OneBot 最小配置&quot;">​</a></h2><p>编辑 <code>config.yml</code>：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">onebot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  websocket-url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ws://127.0.0.1:3001&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  access-token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allow-all-groups</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed-group-ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456789</span></span></code></pre></div><ul><li>OneBot 和 Minecraft 实例在同一台机器时，可以使用 <code>ws://127.0.0.1:&lt;端口&gt;</code>。</li><li>跨主机部署时应使用 <code>wss://</code>，并确保 Java 信任服务端证书。</li><li><code>access-token</code> 必须与 OneBot 配置一致。</li><li><code>allowed-group-ids</code> 为空且 <code>allow-all-groups: false</code> 时，所有群消息都会被拒绝。</li><li>不建议在生产环境使用 <code>allow-all-groups: true</code>。</li></ul><p>启动后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot status</span></span></code></pre></div><p>确认输出中的数据库和 OneBot 状态正常，再继续开启转发、绑定、图片或快捷命令功能。</p><h2 id="单个-bukkit-服务端" tabindex="-1">单个 Bukkit 服务端 <a class="header-anchor" href="#单个-bukkit-服务端" aria-label="Permalink to &quot;单个 Bukkit 服务端&quot;">​</a></h2><p>只安装 <code>ShitBotSpigot-*.jar</code>，保持：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">deployment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  role</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standalone&quot;</span></span></code></pre></div><p>此模式由 Spigot 插件直接连接 OneBot。单实例可以使用默认 SQLite，也可以改用 MySQL。不需要配置 <code>backend-transport</code>。</p><h2 id="bungeecord-或-velocity-群组服" tabindex="-1">BungeeCord 或 Velocity 群组服 <a class="header-anchor" href="#bungeecord-或-velocity-群组服" aria-label="Permalink to &quot;BungeeCord 或 Velocity 群组服&quot;">​</a></h2><p>只需要群聊转发、QQ 绑定和代理侧功能时，在代理安装 <code>ShitBotBungee-*.jar</code> 或 <code>ShitBotVelocity-*.jar</code>。</p><p>如果还需要从 QQ 查询具体子服 TPS、执行子服快捷命令或由后端保存背包快照，则需要：</p><ol><li>在代理安装对应代理版；</li><li>在每个目标 Bukkit 子服安装 Spigot 版；</li><li>将后端 Spigot 的 <code>deployment.role</code> 设为 <code>backend</code>；</li><li>让代理与所有后端连接同一个 MySQL 数据库；</li><li>配置 <code>commands.yml</code> 中的认证命令通道。</li></ol><p>完整步骤见<a href="./proxy-backend.html">代理与后端子服</a>。</p><h2 id="nukkit-mot-单服" tabindex="-1">Nukkit-MOT 单服 <a class="header-anchor" href="#nukkit-mot-单服" aria-label="Permalink to &quot;Nukkit-MOT 单服&quot;">​</a></h2><p>将 <code>ShitBotNukkit-*.jar</code> 放入 Nukkit-MOT 的 <code>plugins/</code> 目录。Nukkit-MOT 是单服平台：</p><ul><li>不使用 <code>deployment.role</code>；</li><li>不配置代理—后端命令通道；</li><li>TPS 和 QQ 快捷命令始终在本服执行；</li><li>可以使用 SQLite 或 MySQL；</li><li>不使用 PictureBridge 客户端协议，媒体标签后会保留原始 URL。</li></ul><h2 id="开启群服互通" tabindex="-1">开启群服互通 <a class="header-anchor" href="#开启群服互通" aria-label="Permalink to &quot;开启群服互通&quot;">​</a></h2><p>两种转发方向默认都关闭。需要时在 <code>config.yml</code> 中分别开启：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">forwarding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  game-to-group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require-prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#qq &quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  group-to-game</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    require-prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#mc &quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    media-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;browser&quot;</span></span></code></pre></div><p>默认用法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Minecraft: #qq 要发送到 QQ 群的内容</span></span>
<span class="line"><span>QQ 群:     #mc 要发送到游戏的内容</span></span></code></pre></div><p>修改完成后执行 <code>/shitbot reload</code>。更多选项见<a href="./configuration.html">配置说明</a>。</p><h2 id="安装完成后的检查" tabindex="-1">安装完成后的检查 <a class="header-anchor" href="#安装完成后的检查" aria-label="Permalink to &quot;安装完成后的检查&quot;">​</a></h2><p>建议依次确认：</p><ol><li><code>/shitbot status</code> 显示数据库可用；</li><li>OneBot 状态为已连接；</li><li>机器人所在群已列入 <code>allowed-group-ids</code>；</li><li>在 QQ 群发送 <code>服务器状态</code> 能收到回复；</li><li>开启转发后，<code>#qq</code> 和 <code>#mc</code> 两个方向均符合预期；</li><li>使用代理—后端模式时，<code>TPS &lt;子服名&gt;</code> 能到达指定子服。</li></ol><p>发生问题时见<a href="./troubleshooting.html">常见问题</a>。</p>`,41)])])}const u=a(l,[["render",n]]);export{c as __pageData,u as default};
